package dev.gbppimentel.zzz;
import java.io.*;import java.nio.file.Files;import java.time.Instant;import org.json.*;
public final class WeeklyHistoryTest {
 static int checks;static void check(boolean v){if(!v)throw new AssertionError("Weekly history "+checks);checks++;}
 public static void main(String[]args)throws Exception{File d=Files.createTempDirectory("weekly-history").toFile();try{String a="1000000001",b="1000000002";long now=Instant.parse("2026-11-28T12:00:00Z").toEpochMilli();check(WeeklyHistory.summary(d,a,now).getInt("remaining")==-1);JSONObject h=new JSONObject().put("remaining",1).put("quotaAt",now).put("lastTriggeredAt",now).put("lastState","complete").put("claimsAt",now);WeeklyHistory.save(d,a,h);check(WeeklyHistory.summary(d,a,now).getInt("remaining")==1);check(WeeklyHistory.summary(d,b,now).getInt("remaining")==-1);check(WeeklyHistory.summary(d,a,WeeklyPolicy.nextReset(now)).getInt("remaining")==-1);check(WeeklyHistory.summary(d,a,now).getLong("lastTriggeredAt")==now);check(WeeklyHistory.summary(d,a,now).getLong("claimsAt")==now);h.put("remaining",0).put("lastState","stopped");WeeklyHistory.save(d,a,h);check(WeeklyHistory.summary(d,a,now).getInt("remaining")==0);WeeklyHistory.save(d,b,new JSONObject().put("lastTriggeredAt",now+1));check(WeeklyHistory.read(d,a).getInt("remaining")==0);boolean rejected=false;try{WeeklyHistory.save(d,"",h);}catch(IOException expected){rejected=true;}check(rejected);System.out.println(checks+" account scoped weekly history checks passed");}finally{for(File f:d.listFiles())f.delete();d.delete();}}
}
